/* Ironlog — the once-only data migrations: each changes records already in
   the log, keeps a rescue copy first, and runs once per log (rules below).
   Split out of io.js (ROADMAP E17 phase 5) so Drive sync and import can both
   run them without importing each other. */
/* imports — generated by r&d/tools/module-map.cjs --sync, not by hand */
import { APP_VERSION } from './core.js';
import { PROGRAM_MANIFEST, PROGRAM_NAMES } from './data.js';
import { KEY, storePut } from './database.js';
import { EXERCISE_CATALOGUE, attachmentsFor, bustCatalogue, completeLeaf, customMovementFor, leafKey, movementById } from './exercises.js';
import { S } from './state.js';
import { bust } from './stats.js';
import { rirOnlySession } from './training.js';
/* end imports */

/* ---------------- migrations ---------------- */
/* A set that points at a custom movement this phone has no record of — it
   came from a Drive backup made before custom movements were synced, or from
   a CSV, which carries only the pointer. Without a record it showed as its
   raw id ("custom-zercher-carry"). The record is rebuilt under the same id
   from the name the set was logged with, so the set itself is untouched. */
export function healCustomMovements() {
  const have = new Set((S.customMovements || []).map(m => m && m.id));
  let n = 0;
  const see = e => {
    const id = e && e.leaf && e.leaf.movement;
    if (typeof id !== 'string' || !id.startsWith('custom-') || have.has(id) || movementById(id)) return;
    const name = (typeof e.legacyName === 'string' && e.legacyName.trim()) || id.slice(7).replace(/-/g, ' ');
    (S.customMovements = S.customMovements || []).push({ ...customMovementFor(name), id });
    have.add(id); n++;
  };
  (S.workouts || []).forEach(w => (w.exercises || []).forEach(see));
  if (S.active) (S.active.exercises || []).forEach(see);
  if (n) bustCatalogue();
  return n;
}
/* ---------------- stored-data migrations (bug sweep 00-B2, Aaron's calls) ----------------
   Each one changes records already in the log, so each follows the same rules:
   - it runs once per log: st.migrations[id] records that it ran, when, from
     which version and what it did;
   - it is idempotent: run twice, the second run changes nothing (the runner
     relies on that: it counts the changes on a copy first);
   - before it touches anything, the whole log as it stood is saved under its
     own rescue key (KEY + '.before-' + id). If that save fails the migration
     doesn't run, and tries again on the next start.
   A migration whose dry run changes nothing is just marked as run. `recheck`
   re-runs named ones regardless of the mark — for records that arrived later
   from Drive (only when they would change something). Returns the notes worth
   telling the lifter. */
const DATA_MIGRATIONS = [
  { id: 'legacy-movements-0.96.0', run: st => repointLegacyMovements(st) },
  { id: 'rir-backfill-skipped-0.96.1', run: st => skipRirBackfills(st) },
  { id: 'relink-plan-sessions-0.96.4', run: st => relinkPlanSessions(st) },
  { id: 'trap-handles-0.98.0', run: st => trapHandles(st) },
];
export async function runDataMigrations(st, recheck = []) {
  if (!st.migrations || typeof st.migrations !== 'object' || Array.isArray(st.migrations)) st.migrations = {};
  const notes = [];
  for (const M of DATA_MIGRATIONS) {
    if (st.migrations[M.id] && !recheck.includes(M.id)) continue;
    let dry;
    try { dry = M.run(structuredClone(st)); } catch (e) { console.warn(`migration ${M.id}: dry run failed`, e); continue; }
    if (dry.changed) {
      const ok = await storePut(`${KEY}.before-${M.id}`, JSON.stringify({ at: Date.now(), version: APP_VERSION, migration: M.id, state: st }));
      if (!ok) { console.warn(`migration ${M.id}: couldn't save the rescue copy, so it didn't run`); continue; }
    }
    const r = dry.changed ? M.run(st) : dry;
    if (!st.migrations[M.id] || r.changed) {
      const { note, ...rest } = r;
      st.migrations[M.id] = { at: Date.now(), v: APP_VERSION, ...rest };
    }
    if (r.changed) console.log(`migration ${M.id}:`, r);
    if (r.changed && r.note) notes.push(r.note);
  }
  if (notes.length) { bustCatalogue(); bust(); }
  return notes;
}
/* 3.4: sessions already backfilled from a RIR-only plan logged every loaded
   set at 0 kg, and those counted as real sets. Each becomes what it was: a
   planned session that didn't happen. It goes into S.misses as skipped, with
   the planned copy kept, so Undo on the calendar puts it back on the plan.
   A backfilled session that has since been edited is left alone — someone
   chose those numbers. */
function skipRirBackfills(st) {
  const r = { changed: 0, skipped: [] };
  const now = Date.now();
  const hit = w => w && w.status === 'completed' && w.source === 'backfill' && !w.edited && (w.loads === 'rir' || w.prog) && rirOnlySession(w);
  const gone = new Set();
  (st.workouts || []).filter(hit).forEach(w => {
    const wo = structuredClone(w);
    wo.status = 'planned';
    ['source', 'backfilled', 'end', 'start', 'summary'].forEach(k => delete wo[k]);
    (wo.exercises || []).forEach(e => (e.sets || []).forEach(s => { s.done = false; }));
    st.misses = Array.isArray(st.misses) ? st.misses : [];
    st.misses.push({ id: 'bf-' + w.id, wid: w.id, date: w.date, name: w.name, prog: w.prog || null, reason: 'other',
      note: 'Backfilled at 0 kg from a plan with no weights — changed to skipped', movedTo: null, at: now, mt: now, wo });
    gone.add(w.id); r.skipped.push(w.id);
  });
  if (gone.size) st.workouts = st.workouts.filter(w => !gone.has(w.id));
  r.changed = gone.size;
  if (r.changed) r.note = `${r.changed} backfilled session${r.changed === 1 ? '' : 's'} from a plan with no weights changed to skipped — ${r.changed === 1 ? 'it' : 'they'} had logged every set at 0 kg`;
  return r;
}
/* 1.8: until 0.90.9, finishing a planned session kept its program link only
   when the session had a block name, so sessions from a program without
   blocks were saved with no `prog` and never counted as Completed. A planned
   session's id is "<program id>#<day>" (progWorkoutId, or the pre-0.10
   positional "<program id>#<n>"), so a finished session with no link is
   relinked when its id starts with exactly one program id this log knows of
   and the rest has that shape. Two candidates, or none: left alone and
   counted. Only `prog` is added; nothing else about the session changes. */
function relinkPlanSessions(st) {
  const r = { changed: 0, relinked: 0, ambiguous: 0 };
  const ids = new Set([...(st.programs || []), ...Object.keys(st.programStarts || {}), ...Object.keys(st.programNames || {}),
    ...Object.keys(PROGRAM_NAMES), ...(PROGRAM_MANIFEST && PROGRAM_MANIFEST.id ? [PROGRAM_MANIFEST.id] : []),
    ...(st.workouts || []).map(w => w.prog), ...(st.misses || []).map(m => m.prog)].filter(x => typeof x === 'string' && x));
  const shape = /^(d\d{4}-\d{2}-\d{2}|w\d+d\d+|\d+)(\.\d+)?$/;
  (st.workouts || []).forEach(w => {
    if (!w || w.status !== 'completed' || w.prog || typeof w.id !== 'string' || !w.id.includes('#')) return;
    const hits = [...ids].filter(p => w.id.startsWith(p + '#') && shape.test(w.id.slice(p.length + 1)));
    if (hits.length === 1) { w.prog = hits[0]; r.relinked++; }
    else if (hits.length > 1) r.ambiguous++;
  });
  r.changed = r.relinked;
  if (r.relinked) r.note = `${r.relinked} finished session${r.relinked === 1 ? '' : 's'} relinked to ${r.relinked === 1 ? 'its' : 'their'} program`;
  return r;
}
/* 0.98.0: a trap bar's high and low handles became the attachment axis, so
   they are separate lifts with separate PRs. Every trap bar set logged before
   had no attachment; Aaron's call is that they were all high handles (his PRs
   are). Each such leaf, and each leaf key written as a string anywhere in the
   log (rest times, goals, priority lifts, bar-speed profiles, the coach),
   moves to high handles. Only movements that now take handles are touched. */
const TRAP_HANDLE_MOVES = () => new Set((EXERCISE_CATALOGUE.movements || [])
  .filter(m => (m.attachments || []).includes('high_handles')).map(m => m.id));
function trapHandles(st) {
  const moves = TRAP_HANDLE_MOVES(), r = { changed: 0, leaves: 0, keys: 0 };
  if (!moves.size) return r;
  const fixStr = s => {
    if (typeof s !== 'string') return s;
    const cut = s.search(/[#|]/), head = cut < 0 ? s : s.slice(0, cut), tail = cut < 0 ? '' : s.slice(cut);
    const p = head.split('/');
    if (p.length !== 4 || !moves.has(p[0]) || p[1] !== 'trap_bar' || p[3] !== 'none') return s;
    return `${p[0]}/trap_bar/${p[2]}/high_handles${tail}`;
  };
  const walk = (o, depth) => {
    if (!o || typeof o !== 'object' || depth > 40) return;
    if (Array.isArray(o)) {
      o.forEach((v, i) => { if (typeof v === 'string') { const n = fixStr(v); if (n !== v) { o[i] = n; r.keys++; } } else walk(v, depth + 1); });
      return;
    }
    if (typeof o.movement === 'string' && moves.has(o.movement) && o.equipment === 'trap_bar' && (!o.attachment || o.attachment === 'none')) {
      o.attachment = 'high_handles'; r.leaves++;
    }
    Object.keys(o).forEach(k => {
      const v = o[k];
      if (typeof v === 'string') { if (k !== 'movement' && k !== 'legacyName') { const n = fixStr(v); if (n !== v) { o[k] = n; r.keys++; } } }
      else walk(v, depth + 1);
      const nk = fixStr(k);
      if (nk !== k) { if (!(nk in o)) o[nk] = o[k]; delete o[k]; r.keys++; }
    });
  };
  Object.keys(st).forEach(k => { if (k !== 'migrations') walk(st[k], 0); });
  r.changed = r.leaves + r.keys;
  if (r.leaves) r.note = `Trap bar high and low handles are now separate lifts — your ${r.leaves} earlier trap bar entr${r.leaves === 1 ? 'y is' : 'ies are'} marked high handles. Change any low-handle ones from the exercise's handle chip.`;
  return r;
}
function legacyMovementMap() {
  const out = {};
  (EXERCISE_CATALOGUE.movements || []).forEach(m => (m.legacyIds || []).forEach(id => { out[id] = m; }));
  return out;
}
/* An axis still at what customMovementFor gave every custom movement
   (barbell, bilateral, no attachment) wasn't chosen: it takes the shipped
   movement's default, so these sets share a history with the ones the program
   now plans (a per-arm landmine press is unilateral). An axis the lifter did
   change is kept if the shipped movement allows it. */
function repointLeaf(l, m) {
  const eq = l.equipment !== 'barbell' && (m.equipment || []).includes(l.equipment) ? l.equipment : undefined;
  const equipment = eq || m.defaultEquipment;
  const ex = l.execution !== 'bilateral' && (m.execution || []).includes(l.execution) ? l.execution : undefined;
  const at = l.attachment && l.attachment !== 'none' && attachmentsFor(m, equipment).includes(l.attachment) ? l.attachment : undefined;
  return completeLeaf(m, { equipment: eq, execution: ex, attachment: at });
}
function repointLegacyMovements(st) {
  const map = legacyMovementMap(), ids = Object.keys(map);
  const r = { changed: 0, leaves: 0, keys: 0, removed: [] };
  if (!ids.length) return r;
  const fixStr = s => {
    if (typeof s !== 'string') return s;
    const id = ids.find(i => s === i || s.startsWith(i + '/'));
    if (!id) return s;
    if (s === id) return map[id].id;
    const cut = s.search(/[#|]/), head = cut < 0 ? s : s.slice(0, cut), tail = cut < 0 ? '' : s.slice(cut);
    const p = head.split('/');
    if (p.length !== 4) return s;
    return leafKey(repointLeaf({ movement: p[0], equipment: p[1], execution: p[2], attachment: p[3] }, map[id])) + tail;
  };
  const walk = (o, depth) => {
    if (!o || typeof o !== 'object' || depth > 40) return;
    if (Array.isArray(o)) {
      o.forEach((v, i) => { if (typeof v === 'string') { const n = fixStr(v); if (n !== v) { o[i] = n; r.keys++; } } else walk(v, depth + 1); });
      return;
    }
    if (typeof o.movement === 'string' && map[o.movement] && typeof o.equipment === 'string') {
      Object.assign(o, repointLeaf(o, map[o.movement])); r.leaves++;
    }
    Object.keys(o).forEach(k => {
      const v = o[k];
      if (typeof v === 'string') { if (k !== 'movement' && k !== 'legacyName') { const n = fixStr(v); if (n !== v) { o[k] = n; r.keys++; } } }
      else walk(v, depth + 1);
      const nk = fixStr(k);
      if (nk !== k) { if (!(nk in o)) o[nk] = o[k]; delete o[k]; r.keys++; }
    });
  };
  // the custom records themselves are removed below, not rewritten
  Object.keys(st).forEach(k => { if (k !== 'customMovements' && k !== 'migrations') walk(st[k], 0); });
  const before = (st.customMovements || []).length;
  if (Array.isArray(st.customMovements)) {
    st.customMovements = st.customMovements.filter(m => {
      const gone = m && map[m.id];
      if (gone) r.removed.push(m.id);
      return !gone;
    });
  }
  r.changed = r.leaves + r.keys + (before - (st.customMovements || []).length);
  if (r.changed) r.note = `${r.removed.length ? r.removed.map(id => map[id].name).join(' and ') : 'Landmine Press and Tibialis Raise'} moved onto the built-in exercise${r.removed.length === 1 ? '' : 's'} — history kept`;
  return r;
}
